INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Prüfung 1: Planen eines Softwareprodukts > Softwarearchitektur > Monolith
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Ist eine monolithische Architektur immer schwerer zu skalieren als eine verteilte Architektur?', 2, '[{"text": "Ja", "correct": true, "because": "Monolithen skalieren oft nur vertikal, was limitiert ist"}, {"text": "Nein", "correct": false, "because": "Skalierung ist schwieriger, aber nicht immer unmöglich"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann ein monolithisches System aus mehreren unabhängigen Modulen bestehen?', 2, '[{"text": "Nein", "correct": true, "because": "Monolithen sind per Definition eng gekoppelt"}, {"text": "Ja", "correct": false, "because": "Unabhängigkeit widerspricht dem Monolith-Konzept"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist die Wartung eines monolithischen Systems immer einfacher als die eines Microservice-Systems?', 2, '[{"text": "Nein", "correct": true, "because": "Komplexität kann Wartung erschweren"}, {"text": "Ja", "correct": false, "because": "Einfachheit ist nicht garantiert"}]'),
('00000000-0000-0000-0000-000000000000', 'Muss ein monolithisches System immer in einer einzigen Programmiersprache geschrieben sein?', 2, '[{"text": "Nein", "correct": true, "because": "Mehrere Sprachen sind möglich, aber unüblich"}, {"text": "Ja", "correct": false, "because": "Keine zwingende Einschränkung"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann ein monolithisches System in kleinere Komponenten aufgeteilt werden, ohne die Architektur zu ändern?', 2, '[{"text": "Nein", "correct": true, "because": "Aufteilung würde den Monolithen auflösen"}, {"text": "Ja", "correct": false, "because": "Komponententrennung verändert die Struktur"}]'),

-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welches Merkmal definiert eine monolithische Architektur am besten?', 2, '[{"text": "Einheitliche Codebasis", "correct": true, "because": "Alle Funktionen in einem Block"}, {"text": "Verteilte Dienste", "correct": false, "because": "Typisch für Microservices"}, {"text": "Hohe Modularität", "correct": false, "because": "Weniger ausgeprägt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Nachteil eines monolithischen Systems ist am häufigsten?', 3, '[{"text": "Schwierige Skalierung", "correct": true, "because": "Vertikale Skalierung ist begrenzt"}, {"text": "Hohe Entwicklungskosten", "correct": false, "because": "Eher gering"}, {"text": "Mangelnde Sicherheit", "correct": false, "because": "Nicht spezifisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Vorteil macht monolithische Systeme für kleine Projekte attraktiv?', 2, '[{"text": "Einfache Bereitstellung", "correct": true, "because": "Ein Paket statt vieler Dienste"}, {"text": "Hohe Flexibilität", "correct": false, "because": "Weniger flexibel"}, {"text": "Geringer Ressourcenverbrauch", "correct": false, "because": "Nicht immer zutreffend"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Technologie ist für monolithische Architekturen am wenigsten typisch?', 2, '[{"text": "Docker-Container", "correct": true, "because": "Eher für Microservices genutzt"}, {"text": "Monolithische Frameworks", "correct": false, "because": "Passen zum Monolith"}, {"text": "Datenbankintegration", "correct": false, "because": "Üblich im Monolith"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Problem tritt bei der Wartung eines monolithischen Systems am ehesten auf?', 2, '[{"text": "Kaskadeneffekte bei Änderungen", "correct": true, "because": "Enge Kopplung führt zu Problemen"}, {"text": "Fehlende Dokumentation", "correct": false, "because": "Nicht spezifisch"}, {"text": "Langsame Bereitstellung", "correct": false, "because": "Eher Vorteil"}]'),

-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Eigenschaften charakterisieren eine monolithische Architektur?', 4, '[{"text": "Einheitliche Bereitstellung", "correct": true, "because": "Alles in einem Paket"}, {"text": "Enge Kopplung", "correct": true, "because": "Komponenten stark verbunden"}, {"text": "Zentrale Codebasis", "correct": true, "because": "Einheitlicher Code"}, {"text": "Hohe Verteilbarkeit", "correct": false, "because": "Typisch für Microservices"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Nachteile hat eine monolithische Architektur?', 3, '[{"text": "Begrenzte Skalierbarkeit", "correct": true, "because": "Nur vertikal skalierbar"}, {"text": "Komplexe Wartung", "correct": true, "because": "Änderungen wirken breit"}, {"text": "Schwierige Modularisierung", "correct": true, "because": "Enge Verknüpfung"}, {"text": "Hohe Entwicklungsgeschwindigkeit", "correct": false, "because": "Eher Vorteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet eine monolithische Architektur?', 4, '[{"text": "Einfache Entwicklung", "correct": true, "because": "Weniger Komplexität anfangs"}, {"text": "Einheitliche Bereitstellung", "correct": true, "because": "Ein Paket"}, {"text": "Geringere Latenz", "correct": true, "because": "Keine Netzwerkaufrufe"}, {"text": "Hohe Flexibilität", "correct": false, "because": "Weniger flexibel"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Herausforderungen treten bei der Weiterentwicklung eines monolithischen Systems auf?', 3, '[{"text": "Technische Schulden", "correct": true, "because": "Alte Strukturen erschweren"}, {"text": "Abhängigkeit von einer Sprache", "correct": true, "because": "Einschränkung möglich"}, {"text": "Komplexe Updates", "correct": true, "because": "Alles muss angepasst werden"}, {"text": "Geringer Ressourcenbedarf", "correct": false, "because": "Eher höher"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aspekte sollten bei der Planung eines monolithischen Systems beachtet werden?', 3, '[{"text": "Zukünftige Skalierbarkeit", "correct": true, "because": "Begrenzung berücksichtigen"}, {"text": "Wartbarkeit", "correct": true, "because": "Komplexität managen"}, {"text": "Integrationsfähigkeit", "correct": true, "because": "Mit anderen Systemen"}, {"text": "Maximale Verteilung", "correct": false, "because": "Nicht monolithisch"}]'),

-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Monolithische Systeme sind einfach bereitzustellen. b) Sie sind immer schwer skalierbar.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Bereitstellung ja, Skalierung nicht immer"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Monolithische Architekturen haben eine enge Kopplung. b) Sie sind flexibel wie Microservices.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Kopplung ja, Flexibilität nein"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Monolithische Systeme eignen sich für kleine Projekte. b) Ihre Wartung ist immer komplexer als bei Microservices.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Kleine Projekte ja, Wartung nicht immer"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) Änderungen in Monolithen können Kaskadeneffekte haben. b) Sie erfordern immer mehrere Sprachen.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Kaskaden ja, Sprachen nicht zwingend"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Monolithische Systeme haben geringere Latenz als verteilte Systeme. b) Sie sind ungeeignet für große Projekte.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Latenz ja, Eignung abhängig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]');

